export function getMatchingProfilesForResult(windowType: string, frameType: string): UPVCProfileSpec[] {
  if (windowType === 'sliding') {
    if (frameType === '2.5-track') {
      return UPVC_16_PROFILES.filter(p => ['GC-10', 'GC-04', 'GC-06', 'GC-12', 'GC-13', 'GC-14', 'GC-07', 'GC-08', 'GC-09'].includes(p.code));
    } else if (frameType === '3-track' || frameType === '3.5-track') {
      return UPVC_16_PROFILES.filter(p => ['GC-11', 'GC-04', 'GC-05', 'GC-06', 'GC-07', 'GC-08', 'GC-09'].includes(p.code));
    } else {
      return UPVC_16_PROFILES.filter(p => ['GC-03', 'GC-04', 'GC-05', 'GC-06', 'GC-07', 'GC-08', 'GC-09'].includes(p.code));
    }
  } else if (windowType === 'open') {
    return UPVC_16_PROFILES.filter(p => ['GC-17', 'GC-18', 'GC-16'].includes(p.code));
  } else if (windowType === 'fixed') {
    return UPVC_16_PROFILES.filter(p => ['GC-17', 'GC-07', 'GC-15'].includes(p.code));
  } else if (windowType === 'ventilator') {
    return UPVC_16_PROFILES.filter(p => ['GC-17'].includes(p.code));
  }
  return UPVC_16_PROFILES;
}
